style.css:
@-moz-document domain("roblox.com") {
body, 
    .content, 
    .container-main, 
    .rbx-body, 
    .page-content, 
    #roblox-body, 
    .wrapper, 
    .rbx-page-content {
        background-color: #000000 !important;
        background-image: none !important;
        background: #000000 !important;
    }

    /* Ensure nested elements don't override */
    div[class*="container"], 
    div[class*="content"], 
    div[class*="page"], 
    section, 
    main {
        background-color: #000000 !important;
        background-image: none !important;
    }
}
